def pasar_a_tres_estados(apps, schema_editor):
    # en revision -> pendiente, rechazado -> resuelto (quedan cerrados)
    Reporte = apps.get_model("mi_app", "Reporte")
    Reporte.objects.filter(estado="en_revision").update(estado="pendiente")
    Reporte.objects.filter(estado="rechazado").update(estado="resuelto")


def crear_perfiles(apps, schema_editor):
    # las cuentas que ya existian quedan como estudiantes
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Perfil = apps.get_model("mi_app", "Perfil")
    Universidad = apps.get_model("mi_app", "Universidad")
    unis = list(Universidad.objects.all())
    for u in User.objects.filter(is_superuser=False):
        dominio = (u.email or u.username).rsplit("@", 1)[-1].lower()
        uni = next((x for x in unis if dominio == x.dominio or dominio.endswith("." + x.dominio)), None)
        Perfil.objects.get_or_create(usuario=u, defaults={"universidad": uni})


